class ProduitVendableRow extends DataClass
    implements Insertable<ProduitVendableRow> {
  /// UUID genere au poste (DV-19, `46_`) : un produit cree sur deux postes ne
  /// peut pas porter le meme entier. Les anciens produits recoivent le leur a la
  /// migration v33.
  final String id;

  /// ⚠️ AJOUTEE — colonne « SKU », 1ʳᵉ du tableau de `catalogue-produits.html`
  /// (l.126) et absente de Doc D1. Genere sous la forme 'PRD-001' faute de
  /// regle de codification documentee.
  final String? sku;
  final String name;

  /// 'Avicole', 'Commerce Annexe', 'Cuniculture', 'Pisciculture'
  /// (valeurs reellement presentes dans `logialvia-store.js`, plus larges que
  /// les 2 valeurs listees par Doc D1 — voir note du seeder).
  final String cat;
  final double price;

  /// Prix haut de la fourchette de negociation, si le produit en a une.
  final double? priceMax;
  final String unit;

  /// Nom d'icone Material Symbols, tel quel depuis le prototype.
  final String icon;

  /// Coût de revient unitaire — ce que le produit a coûté, pas ce qu'il se
  /// vend.
  ///
  /// ⚠️ Le prototype ne le connaît pas et le confond avec le prix : sa colonne
  /// « CMUP » du Rapport de Stocks reprend **exactement** le prix de vente du
  /// catalogue (`price:6000` / `cmup:6000` pour le Goliath mature). Valoriser
  /// un stock à son prix de vente le surévalue et anticipe une marge non
  /// réalisée — un goliath encore dans l'enclos n'a pas rapporté 6 000 F.
  ///
  /// `null` = non renseigné. Le stock de ce produit n'est alors **pas
  /// valorisé** ; le prix de vente ne lui est jamais substitué.
  final double? coutRevient;

  /// Groupe de taxe de la grille MeCeF — la lettre imprimee en face de chaque
  /// ligne d'une facture normalisee.
  ///
  /// Defaut `'A'`, exonere : ALLMANY vend d'abord des produits d'elevage non
  /// transformes. Taxer par defaut aurait ete le pire choix -- une facture qui
  /// reclame une TVA non due engage l'entreprise, et personne ne verifie un
  /// champ qui parait deja rempli correctement.
  final String groupeTaxe;
  final int stock;
  final int threshold;

  /// Renseigne si le produit est un animal vivant issu d'une filiere.
  final String? espece;
  const ProduitVendableRow({
    required this.id,
    this.sku,
    required this.name,
    required this.cat,
    required this.price,
    this.priceMax,
    required this.unit,
    required this.icon,
    this.coutRevient,
    required this.groupeTaxe,
    required this.stock,
    required this.threshold,
    this.espece,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    if (!nullToAbsent || sku != null) {
      map['sku'] = Variable<String>(sku);
    }
    map['name'] = Variable<String>(name);
    map['cat'] = Variable<String>(cat);
    map['price'] = Variable<double>(price);
    if (!nullToAbsent || priceMax != null) {
      map['price_max'] = Variable<double>(priceMax);
    }
    map['unit'] = Variable<String>(unit);
    map['icon'] = Variable<String>(icon);
    if (!nullToAbsent || coutRevient != null) {
      map['cout_revient'] = Variable<double>(coutRevient);
    }
    map['groupe_taxe'] = Variable<String>(groupeTaxe);
    map['stock'] = Variable<int>(stock);
    map['threshold'] = Variable<int>(threshold);
    if (!nullToAbsent || espece != null) {
      map['espece'] = Variable<String>(espece);
    }
    return map;
  }

  ProduitsVendablesCompanion toCompanion(bool nullToAbsent) {
    return ProduitsVendablesCompanion(
      id: Value(id),
      sku: sku == null && nullToAbsent ? const Value.absent() : Value(sku),
      name: Value(name),
      cat: Value(cat),
      price: Value(price),
      priceMax: priceMax == null && nullToAbsent
          ? const Value.absent()
          : Value(priceMax),
      unit: Value(unit),
      icon: Value(icon),
      coutRevient: coutRevient == null && nullToAbsent
          ? const Value.absent()
          : Value(coutRevient),
      groupeTaxe: Value(groupeTaxe),
      stock: Value(stock),
      threshold: Value(threshold),
      espece: espece == null && nullToAbsent
          ? const Value.absent()
          : Value(espece),
    );
  }

  factory ProduitVendableRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return ProduitVendableRow(
      id: serializer.fromJson<String>(json['id']),
      sku: serializer.fromJson<String?>(json['sku']),
      name: serializer.fromJson<String>(json['name']),
      cat: serializer.fromJson<String>(json['cat']),
      price: serializer.fromJson<double>(json['price']),
      priceMax: serializer.fromJson<double?>(json['priceMax']),
      unit: serializer.fromJson<String>(json['unit']),
      icon: serializer.fromJson<String>(json['icon']),
      coutRevient: serializer.fromJson<double?>(json['coutRevient']),
      groupeTaxe: serializer.fromJson<String>(json['groupeTaxe']),
      stock: serializer.fromJson<int>(json['stock']),
      threshold: serializer.fromJson<int>(json['threshold']),
      espece: serializer.fromJson<String?>(json['espece']),
    );
  }
  @override
