          ? const Value.absent()
          : Value(livraisonFrais),
      livraisonAdresse: livraisonAdresse == null && nullToAbsent
          ? const Value.absent()
          : Value(livraisonAdresse),
      livraisonContact: livraisonContact == null && nullToAbsent
          ? const Value.absent()
          : Value(livraisonContact),
      echeance: echeance == null && nullToAbsent
          ? const Value.absent()
          : Value(echeance),
      ligneMobileMoney: ligneMobileMoney == null && nullToAbsent
