class FactureRow extends DataClass implements Insertable<FactureRow> {
  /// UUID de la facture (DV-19) : l'identite SYNCHRONISEE. La cle primaire reste
  /// [ref] (les lignes et les ventes s'y rattachent par texte) ; `ref` est le
  /// numero OFFICIEL de la piece (`FV-P2-2026-001`, DV-21), jamais renumerote.
  final String id;

  /// `null` : facture emise sur CE poste. Sinon l'identifiant du poste qui l'a
  /// emise (facture absorbee du serveur). **Seul le poste emetteur transmet** a la
  /// DGI : une facture d'un autre poste n'offre ni transmission ni saisie
  /// manuelle, pour qu'elle ne soit pas normalisee deux fois (`46e_` §3).
  final String? origine;

  /// `pending` · `synced` · `conflict`.
  final String syncStatus;
  final String? syncMotif;

  /// Instant de SAISIE (UTC, ISO 8601, microsecondes) : emission, puis derniere
  /// transmission ou saisie du code. Jamais l'instant d'envoi.
  final String updatedAt;

  /// 'FV-P2-2026-001' / 'FA-P2-2026-001' (poste appaire) ou 'FV-2026-001'.
  final String ref;

  /// [TypeFacture.vente] ou [TypeFacture.avoir].
  final String type;

  /// Vente d'origine. `null` pour une facture saisie sans passage en caisse.
  final String? venteRef;

  /// Facture corrigée — obligatoire sur un avoir, toujours nulle sur une
  /// facture de vente.
  final String? origineRef;
  final DateTime dateFacture;
  final String client;

  /// IFU du client. Facultatif : un particulier n'en a pas.
  final String? clientIfu;
  final String? clientAdresse;
  final double totalHt;
  final double totalTaxe;
  final double totalTtc;

  /// Motif de l'avoir — erreur de facturation, retour, annulation.
  final String? motif;

  /// `aTransmettre`, `normalisee` ou `rejetee`. Voir `StatutFacture`.
  final String statut;

  /// Code MeCeF/DGI de normalisation.
  final String? codeMecef;

  /// Numéro d'Identification de la Machine ayant normalisé la facture.
  final String? nim;

  /// Compteur de la DGI, tel quel : « 12/50 ».
  final String? compteur;

  /// Lien de vérification renvoyé par la DGI, imprimé en clair sous la
  /// facture. Aucun QR n'est dessiné tant qu'on n'a pas ce lien : un QR
  /// fabriqué localement ne vérifierait rien.
  final String? lienVerification;
  final DateTime? dateNormalisation;

  /// Message d'erreur de la dernière tentative de transmission, s'il y en a
  /// eu une. Sert à expliquer un statut `rejetee` plutôt qu'à le subir.
  final String? erreurTransmission;
  final DateTime creeLe;
  const FactureRow({
    required this.id,
    this.origine,
    required this.syncStatus,
    this.syncMotif,
    required this.updatedAt,
    required this.ref,
    required this.type,
    this.venteRef,
    this.origineRef,
    required this.dateFacture,
    required this.client,
    this.clientIfu,
    this.clientAdresse,
    required this.totalHt,
    required this.totalTaxe,
    required this.totalTtc,
    this.motif,
    required this.statut,
    this.codeMecef,
    this.nim,
    this.compteur,
    this.lienVerification,
    this.dateNormalisation,
    this.erreurTransmission,
    required this.creeLe,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    if (!nullToAbsent || origine != null) {
      map['origine'] = Variable<String>(origine);
    }
    map['sync_status'] = Variable<String>(syncStatus);
    if (!nullToAbsent || syncMotif != null) {
      map['sync_motif'] = Variable<String>(syncMotif);
    }
    map['updated_at'] = Variable<String>(updatedAt);
    map['ref'] = Variable<String>(ref);
    map['type'] = Variable<String>(type);
    if (!nullToAbsent || venteRef != null) {
      map['vente_ref'] = Variable<String>(venteRef);
    }
    if (!nullToAbsent || origineRef != null) {
      map['origine_ref'] = Variable<String>(origineRef);
    }
    map['date_facture'] = Variable<DateTime>(dateFacture);
    map['client'] = Variable<String>(client);
    if (!nullToAbsent || clientIfu != null) {
      map['client_ifu'] = Variable<String>(clientIfu);
    }
    if (!nullToAbsent || clientAdresse != null) {
      map['client_adresse'] = Variable<String>(clientAdresse);
    }
    map['total_ht'] = Variable<double>(totalHt);
    map['total_taxe'] = Variable<double>(totalTaxe);
    map['total_ttc'] = Variable<double>(totalTtc);
    if (!nullToAbsent || motif != null) {
      map['motif'] = Variable<String>(motif);
    }
    map['statut'] = Variable<String>(statut);
    if (!nullToAbsent || codeMecef != null) {
      map['code_mecef'] = Variable<String>(codeMecef);
    }
    if (!nullToAbsent || nim != null) {
      map['nim'] = Variable<String>(nim);
    }
    if (!nullToAbsent || compteur != null) {
      map['compteur'] = Variable<String>(compteur);
    }
    if (!nullToAbsent || lienVerification != null) {
      map['lien_verification'] = Variable<String>(lienVerification);
    }
    if (!nullToAbsent || dateNormalisation != null) {
      map['date_normalisation'] = Variable<DateTime>(dateNormalisation);
    }
    if (!nullToAbsent || erreurTransmission != null) {
      map['erreur_transmission'] = Variable<String>(erreurTransmission);
    }
    map['cree_le'] = Variable<DateTime>(creeLe);
    return map;
  }

