    map['prix_unitaire_ht'] = Variable<double>(prixUnitaireHt);
    map['groupe_taxe'] = Variable<String>(groupeTaxe);
    map['taux_taxe'] = Variable<double>(tauxTaxe);
    map['montant_ht'] = Variable<double>(montantHt);
    map['montant_taxe'] = Variable<double>(montantTaxe);
    return map;
  }

