class CompteRow extends DataClass implements Insertable<CompteRow> {
  /// Ex. '571' (Caisse), '702' (Ventes de produits finis).
  final String numeroCompte;
  final String libelle;

  /// Classe SYSCOHADA, 1 caractère de '1' à '7'.
  final String classe;

  /// Un compte archivé n'est plus proposé à la saisie mais reste dans
  /// l'historique — l'écran Plan Comptable propose « Archiver », pas
  /// « Supprimer ».
  final bool archive;
  const CompteRow({
    required this.numeroCompte,
    required this.libelle,
    required this.classe,
    required this.archive,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['numero_compte'] = Variable<String>(numeroCompte);
    map['libelle'] = Variable<String>(libelle);
    map['classe'] = Variable<String>(classe);
    map['archive'] = Variable<bool>(archive);
    return map;
  }

  PlanComptableCompanion toCompanion(bool nullToAbsent) {
    return PlanComptableCompanion(
      numeroCompte: Value(numeroCompte),
      libelle: Value(libelle),
      classe: Value(classe),
      archive: Value(archive),
    );
  }

  factory CompteRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return CompteRow(
      numeroCompte: serializer.fromJson<String>(json['numeroCompte']),
      libelle: serializer.fromJson<String>(json['libelle']),
      classe: serializer.fromJson<String>(json['classe']),
      archive: serializer.fromJson<bool>(json['archive']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'numeroCompte': serializer.toJson<String>(numeroCompte),
      'libelle': serializer.toJson<String>(libelle),
      'classe': serializer.toJson<String>(classe),
      'archive': serializer.toJson<bool>(archive),
    };
  }

  CompteRow copyWith({
    String? numeroCompte,
    String? libelle,
    String? classe,
    bool? archive,
  }) => CompteRow(
    numeroCompte: numeroCompte ?? this.numeroCompte,
    libelle: libelle ?? this.libelle,
    classe: classe ?? this.classe,
    archive: archive ?? this.archive,
  );
  CompteRow copyWithCompanion(PlanComptableCompanion data) {
    return CompteRow(
      numeroCompte: data.numeroCompte.present
          ? data.numeroCompte.value
          : this.numeroCompte,
      libelle: data.libelle.present ? data.libelle.value : this.libelle,
      classe: data.classe.present ? data.classe.value : this.classe,
      archive: data.archive.present ? data.archive.value : this.archive,
    );
  }

  @override
  String toString() {
    return (StringBuffer('CompteRow(')
          ..write('numeroCompte: $numeroCompte, ')
          ..write('libelle: $libelle, ')
          ..write('classe: $classe, ')
          ..write('archive: $archive')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(numeroCompte, libelle, classe, archive);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is CompteRow &&
          other.numeroCompte == this.numeroCompte &&
          other.libelle == this.libelle &&
          other.classe == this.classe &&
          other.archive == this.archive);
}

