      journalCode: Value(journalCode),
      numeroPiece: numeroPiece == null && nullToAbsent
          ? const Value.absent()
          : Value(numeroPiece),
      venteRef: venteRef == null && nullToAbsent
          ? const Value.absent()
          : Value(venteRef),
      achatRef: achatRef == null && nullToAbsent
          ? const Value.absent()
          : Value(achatRef),
      axeAnalytique: axeAnalytique == null && nullToAbsent
          ? const Value.absent()
          : Value(axeAnalytique),
      isLocked: Value(isLocked),
      contrepasseDe: contrepasseDe == null && nullToAbsent
          ? const Value.absent()
          : Value(contrepasseDe),
      origine: origine == null && nullToAbsent
          ? const Value.absent()
          : Value(origine),
      syncStatus: Value(syncStatus),
      syncMotif: syncMotif == null && nullToAbsent
          ? const Value.absent()
          : Value(syncMotif),
      updatedAt: Value(updatedAt),
    );
  }

